insert into public.standards (id, framework, code, grade_bands, description_en, description_es) values
  ('NGS.1', 'NGS', '1', '{K-2,3-5,6-8}', 'How to use maps and other geographic representations, geospatial technologies, and spatial thinking to understand and communicate information', 'Cómo usar mapas y otras representaciones geográficas, tecnologías geoespaciales y el pensamiento espacial para comprender y comunicar información'),
  ('NGS.2', 'NGS', '2', '{K-2,3-5,6-8}', 'How to use mental maps to organize information about people, places, and environments in a spatial context', 'Cómo usar mapas mentales para organizar información sobre personas, lugares y entornos en un contexto espacial'),
  ('NGS.3', 'NGS', '3', '{K-2,3-5,6-8}', 'How to analyze the spatial organization of people, places, and environments on Earth''s surface', 'Cómo analizar la organización espacial de personas, lugares y entornos en la superficie de la Tierra'),
  ('NGS.4', 'NGS', '4', '{K-2,3-5,6-8}', 'The physical and human characteristics of places', 'Las características físicas y humanas de los lugares'),
  ('NGS.5', 'NGS', '5', '{K-2,3-5,6-8}', 'That people create regions to interpret Earth''s complexity', 'Que las personas crean regiones para interpretar la complejidad de la Tierra'),
  ('NGS.6', 'NGS', '6', '{K-2,3-5,6-8}', 'How culture and experience influence people''s perceptions of places and regions', 'Cómo la cultura y la experiencia influyen en la percepción que las personas tienen de lugares y regiones'),
  ('NGS.7', 'NGS', '7', '{K-2,3-5,6-8}', 'The physical processes that shape the patterns of Earth''s surface', 'Los procesos físicos que dan forma a los patrones de la superficie de la Tierra'),
  ('NGS.8', 'NGS', '8', '{K-2,3-5,6-8}', 'The characteristics and spatial distribution of ecosystems and biomes on Earth''s surface', 'Las características y la distribución espacial de los ecosistemas y biomas en la superficie de la Tierra'),
  ('NGS.9', 'NGS', '9', '{K-2,3-5,6-8}', 'The characteristics, distribution, and migration of human populations on Earth''s surface', 'Las características, la distribución y la migración de las poblaciones humanas en la superficie de la Tierra'),
  ('NGS.10', 'NGS', '10', '{K-2,3-5,6-8}', 'The characteristics, distribution, and complexity of Earth''s cultural mosaics', 'Las características, la distribución y la complejidad de los mosaicos culturales de la Tierra'),
  ('NGS.11', 'NGS', '11', '{K-2,3-5,6-8}', 'The patterns and networks of economic interdependence on Earth''s surface', 'Los patrones y las redes de interdependencia económica en la superficie de la Tierra'),
  ('NGS.12', 'NGS', '12', '{K-2,3-5,6-8}', 'The processes, patterns, and functions of human settlement', 'Los procesos, patrones y funciones de los asentamientos humanos'),
  ('NGS.13', 'NGS', '13', '{K-2,3-5,6-8}', 'How the forces of cooperation and conflict among people influence the division and control of Earth''s surface', 'Cómo la cooperación y el conflicto entre las personas influyen en la división y el control de la superficie de la Tierra'),
  ('NGS.14', 'NGS', '14', '{K-2,3-5,6-8}', 'How human actions modify the physical environment', 'Cómo las acciones humanas modifican el medio físico'),
  ('NGS.15', 'NGS', '15', '{K-2,3-5,6-8}', 'How physical systems affect human systems', 'Cómo los sistemas físicos afectan a los sistemas humanos'),
  ('NGS.16', 'NGS', '16', '{K-2,3-5,6-8}', 'The changes that occur in the meaning, use, distribution, and importance of resources', 'Los cambios en el significado, el uso, la distribución y la importancia de los recursos'),
  ('NGS.17', 'NGS', '17', '{K-2,3-5,6-8}', 'How to apply geography to interpret the past', 'Cómo aplicar la geografía para interpretar el pasado'),
  ('NGS.18', 'NGS', '18', '{K-2,3-5,6-8}', 'How to apply geography to interpret the present and plan for the future', 'Cómo aplicar la geografía para interpretar el presente y planificar el futuro')
insert into public.content_items (id, version, kind, status, grade_bands, standard_ids, country_codes, data) values
  ('country:AD', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AD}', '{"iso2":"AD","iso3":"AND","name":{"en":"Andorra","es":"Andorra"},"capital":{"name":{"en":"Andorra la Vella","es":"Andorra la Vella"},"coord":[1.516,42.5]},"region":"Europe","subregion":"Southern Europe","center":[1.539,42.548],"flag":{"path":"flags/ad.svg","alt":{"en":"Flag of Andorra: blue, yellow and red vertical stripes, with a coat of arms in the middle.","es":"Bandera de Andorra: franjas verticales azul, amarilla y roja, con un escudo en el centro."}},"languages":[{"en":"Catalan","es":"Catalán"}],"currency":{"code":"EUR","name":{"en":"Euro","es":"Euro"}},"greeting":{"text":"Bon dia","ttsLang":"ca-ES","meaning":{"en":"Good morning (in Catalan)","es":"Buenos días (en catalán)"}},"facts":[{"en":"Andorra has two co-princes: the president of France and a Spanish bishop.","es":"Andorra tiene dos copríncipes: el presidente de Francia y un obispo español."},{"en":"Andorra la Vella is the highest capital city in Europe.","es":"Andorra la Vieja es la capital más alta de Europa."}],"clues":[{"id":"AD-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: blue, yellow and red vertical stripes, with a coat of arms in the middle.","es":"Dibujó una bandera: franjas verticales azul, amarilla y roja, con un escudo en el centro."},"standardIds":["NGS.10","NGS.13"]},{"id":"AD-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief went skiing in the Pyrenees, in a tiny country between France and Spain.","es":"Fue a esquiar a los Pirineos, en un país pequeñito entre Francia y España."},"standardIds":["NGS.4","NGS.17"]},{"id":"AD-food-1","skill":"food","difficulty":2,"text":{"en":"The thief ate trinxat, mashed cabbage and potato with bacon.","es":"Comió trinxat, puré de col y papa con tocino."},"standardIds":["NGS.10","NGS.16"]},{"id":"AD-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief spotted chamois, nimble mountain goats, on rocky slopes.","es":"Vio rebecos, ágiles cabras de montaña, en laderas rocosas."},"standardIds":["NGS.8"]},{"id":"AD-language-1","skill":"language","difficulty":2,"text":{"en":"The thief practiced Catalan, the only official language here.","es":"Practicó catalán, el único idioma oficial aquí."},"standardIds":["NGS.10"]}]}'::jsonb),
  ('country:AE', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.11,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AE}', '{"iso2":"AE","iso3":"ARE","name":{"en":"United Arab Emirates","es":"Emiratos Árabes Unidos"},"capital":{"name":{"en":"Abu Dhabi","es":"Abu Dabi"},"coord":[54.367,24.467]},"region":"Asia","subregion":"Western Asia","center":[54.547,23.466],"flag":{"path":"flags/ae.svg","alt":{"en":"Flag of United Arab Emirates: green, white and black stripes, with a red vertical band on the left.","es":"Bandera de Emiratos Árabes Unidos: franjas verde, blanca y negra, con una banda vertical roja a la izquierda."}},"languages":[{"en":"Arabic","es":"Árabe"}],"currency":{"code":"AED","name":{"en":"United Arab Emirates Dirham","es":"Dírham de los Emiratos Árabes Unidos"}},"greeting":{"text":"Marhaba","ttsLang":"ar-SA","meaning":{"en":"Hello","es":"Hola"}},"facts":[{"en":"The United Arab Emirates is made up of seven emirates.","es":"Los Emiratos Árabes Unidos están formados por siete emiratos."},{"en":"The Burj Khalifa in Dubai is more than 828 meters tall.","es":"El Burj Khalifa, en Dubái, mide más de 828 metros de altura."}],"clues":[{"id":"AE-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: green, white and black stripes, with a red vertical band on the left.","es":"Dibujó una bandera: franjas verde, blanca y negra, con una banda vertical roja a la izquierda."},"standardIds":["NGS.10","NGS.13"]},{"id":"AE-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief rode the elevator up the Burj Khalifa, the tallest building in the world.","es":"Subió en ascensor al Burj Khalifa, el edificio más alto del mundo."},"standardIds":["NGS.4","NGS.17"]},{"id":"AE-food-1","skill":"food","difficulty":2,"text":{"en":"The thief ate luqaimat, sweet fried dough balls drizzled with date syrup.","es":"Comió luqaimat, bolitas dulces de masa frita bañadas en sirope de dátil."},"standardIds":["NGS.10","NGS.16"]},{"id":"AE-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief watched falcons, the national bird, at a falcon hospital.","es":"Vio halcones, el ave nacional, en un hospital de halcones."},"standardIds":["NGS.8"]},{"id":"AE-currency-1","skill":"currency","difficulty":3,"text":{"en":"The thief paid in dirhams.","es":"Pagó en dírhams."},"standardIds":["NGS.11"]}]}'::jsonb),
  ('country:AF', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AF}', '{"iso2":"AF","iso3":"AFG","name":{"en":"Afghanistan","es":"Afganistán"},"capital":{"name":{"en":"Kabul","es":"Kabul"},"coord":[69.181,34.519]},"region":"Asia","subregion":"Southern Asia","center":[66.497,34.164],"flag":{"path":"flags/af.svg","alt":{"en":"Flag of Afghanistan: black, red and green vertical stripes, with a white emblem of a mosque in the middle.","es":"Bandera de Afganistán: franjas verticales negra, roja y verde, con un emblema blanco de una mezquita en el centro."}},"languages":[{"en":"Pashto","es":"Pastún"},{"en":"Dari","es":"Darí"}],"currency":{"code":"AFN","name":{"en":"Afghan Afghani","es":"Afgani afgano"}},"greeting":{"text":"Salaam","ttsLang":"fa-IR","meaning":{"en":"Hello","es":"Hola"}},"facts":[{"en":"Afghanistan is landlocked and very mountainous, crossed by the Hindu Kush range.","es":"Afganistán no tiene salida al mar y es muy montañoso; lo atraviesa la cordillera del Hindu Kush."},{"en":"Buzkashi, a game played on horseback, is Afghanistan''s national sport.","es":"El buzkashi, un juego a caballo, es el deporte nacional de Afganistán."}],"clues":[{"id":"AF-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: black, red and green vertical stripes, with a white emblem of a mosque in the middle.","es":"Dibujó una bandera: franjas verticales negra, roja y verde, con un emblema blanco de una mezquita en el centro."},"standardIds":["NGS.10","NGS.13"]},{"id":"AF-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief visited the Blue Mosque of Mazar-i-Sharif, covered in shining blue tiles.","es":"Visitó la Mezquita Azul de Mazar-e Sharif, cubierta de azulejos azules brillantes."},"standardIds":["NGS.4","NGS.17"]},{"id":"AF-food-1","skill":"food","difficulty":2,"text":{"en":"The thief ate Kabuli pulao, rice with carrots, raisins and lamb.","es":"Comió kabuli pulao, arroz con zanahorias, pasas y cordero."},"standardIds":["NGS.10","NGS.16"]},{"id":"AF-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief searched the Wakhan Corridor for snow leopards and Marco Polo sheep.","es":"Buscó leopardos de las nieves y ovejas de Marco Polo en el corredor de Wakhan."},"standardIds":["NGS.8"]},{"id":"AF-language-1","skill":"language","difficulty":2,"text":{"en":"The thief practiced Pashto and Dari, the two official languages.","es":"Practicó pastún y darí, los dos idiomas oficiales."},"standardIds":["NGS.10"]}]}'::jsonb),
  ('country:AG', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.11,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AG}', '{"iso2":"AG","iso3":"ATG","name":{"en":"Antigua and Barbuda","es":"Antigua y Barbuda"},"capital":{"name":{"en":"St. John''s","es":"Saint John''s"},"coord":[-61.85,17.118]},"region":"Americas","subregion":"Caribbean","center":[-61.791,17.352],"flag":{"path":"flags/ag.svg","alt":{"en":"Flag of Antigua and Barbuda: red, with a V-shaped triangle of black, blue and white holding a golden rising sun.","es":"Bandera de Antigua y Barbuda: roja, con un triángulo en forma de V negro, azul y blanco que tiene un sol naciente dorado."}},"languages":[{"en":"English","es":"Inglés"}],"currency":{"code":"XCD","name":{"en":"East Caribbean Dollar","es":"Dólar del Caribe Oriental"}},"greeting":{"text":"Hello","ttsLang":"en-GB","meaning":{"en":"Hello","es":"Hola"}},"facts":[{"en":"Antigua is said to have 365 beaches, one for every day of the year.","es":"Dicen que Antigua tiene 365 playas, una para cada día del año."},{"en":"Barbuda''s Codrington Lagoon has one of the largest frigatebird colonies in the world.","es":"La laguna Codrington, en Barbuda, tiene una de las colonias de fragatas más grandes del mundo."}],"clues":[{"id":"AG-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: red, with a V-shaped triangle of black, blue and white holding a golden rising sun.","es":"Dibujó una bandera: roja, con un triángulo en forma de V negro, azul y blanco que tiene un sol naciente dorado."},"standardIds":["NGS.10","NGS.13"]},{"id":"AG-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief toured Nelson''s Dockyard, an old naval harbor still in use today.","es":"Recorrió el astillero de Nelson, un antiguo puerto naval que todavía se usa."},"standardIds":["NGS.4","NGS.17"]},{"id":"AG-food-1","skill":"food","difficulty":2,"text":{"en":"The thief ate fungie and pepperpot, the national dish.","es":"Comió fungie con pepperpot, el plato nacional."},"standardIds":["NGS.10","NGS.16"]},{"id":"AG-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief visited a huge frigatebird colony on the smaller of the two islands.","es":"Visitó una enorme colonia de fragatas en la más pequeña de las dos islas."},"standardIds":["NGS.8"]},{"id":"AG-currency-1","skill":"currency","difficulty":3,"text":{"en":"The thief paid in Eastern Caribbean dollars.","es":"Pagó en dólares del Caribe Oriental."},"standardIds":["NGS.11"]}]}'::jsonb),
  ('country:AL', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AL}', '{"iso2":"AL","iso3":"ALB","name":{"en":"Albania","es":"Albania"},"capital":{"name":{"en":"Tirana","es":"Tirana"},"coord":[19.819,41.328]},"region":"Europe","subregion":"Southern Europe","center":[20.114,40.655],"flag":{"path":"flags/al.svg","alt":{"en":"Flag of Albania: red with a black double-headed eagle in the middle.","es":"Bandera de Albania: roja con un águila bicéfala negra en el centro."}},"languages":[{"en":"Albanian","es":"Albanés"}],"currency":{"code":"ALL","name":{"en":"Albanian Lek","es":"Lek albanés"}},"greeting":{"text":"Përshëndetje","ttsLang":"sq-AL","meaning":{"en":"Hello","es":"Hola"}},"facts":[{"en":"Albania''s own name for itself, Shqipëria, is often linked to the word for ''eagle.''","es":"El nombre que Albania se da a sí misma, Shqipëria, suele relacionarse con la palabra ''águila''."},{"en":"In Albania, a nod often means ''no'' and a head shake often means ''yes.''","es":"En Albania, asentir con la cabeza suele significar ''no'' y negar suele significar ''sí''."}],"clues":[{"id":"AL-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: red with a black double-headed eagle in the middle.","es":"Dibujó una bandera: roja con un águila bicéfala negra en el centro."},"standardIds":["NGS.10","NGS.13"]},{"id":"AL-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief explored the ancient ruins of Butrint, near the sea.","es":"Exploró las antiguas ruinas de Butrinto, cerca del mar."},"standardIds":["NGS.4","NGS.17"]},{"id":"AL-food-1","skill":"food","difficulty":2,"text":{"en":"The thief ate tavë kosi, baked lamb with yogurt and rice.","es":"Comió tavë kosi, cordero al horno con yogur y arroz."},"standardIds":["NGS.10","NGS.16"]},{"id":"AL-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief looked for the rare Balkan lynx in the mountains.","es":"Buscó el raro lince balcánico en las montañas."},"standardIds":["NGS.8"]},{"id":"AL-language-1","skill":"language","difficulty":2,"text":{"en":"The thief practiced a language that has no close relatives in Europe.","es":"Practicó un idioma que no tiene parientes cercanos en Europa."},"standardIds":["NGS.10"]}]}'::jsonb),
  ('country:AM', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AM}', '{"iso2":"AM","iso3":"ARM","name":{"en":"Armenia","es":"Armenia"},"capital":{"name":{"en":"Yerevan","es":"Ereván"},"coord":[44.512,40.183]},"region":"Asia","subregion":"Western Asia","center":[44.801,40.459],"flag":{"path":"flags/am.svg","alt":{"en":"Flag of Armenia: red, blue and orange horizontal stripes.","es":"Bandera de Armenia: franjas horizontales roja, azul y naranja."}},"languages":[{"en":"Armenian","es":"Armenio"}],"currency":{"code":"AMD","name":{"en":"Armenian Dram","es":"Dram armenio"}},"greeting":{"text":"Barev","ttsLang":"hy-AM","meaning":{"en":"Hello","es":"Hola"}},"facts":[{"en":"In 301, Armenia became the first country to make Christianity its official religion.","es":"En el año 301, Armenia fue el primer país en adoptar el cristianismo como religión oficial."},{"en":"Mount Ararat, a symbol of Armenia, can be seen from Yerevan.","es":"El monte Ararat, un símbolo de Armenia, se puede ver desde Ereván."}],"clues":[{"id":"AM-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: red, blue and orange horizontal stripes.","es":"Dibujó una bandera: franjas horizontales roja, azul y naranja."},"standardIds":["NGS.10","NGS.13"]},{"id":"AM-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief rode the Wings of Tatev, a very long cable car, to a mountaintop monastery.","es":"Viajó en las Alas de Tatev, un teleférico muy largo, hasta un monasterio en la montaña."},"standardIds":["NGS.4","NGS.17"]},{"id":"AM-food-1","skill":"food","difficulty":2,"text":{"en":"The thief ate lavash, a thin flatbread baked on the walls of a clay oven.","es":"Comió lavash, un pan plano y fino horneado en las paredes de un horno de barro."},"standardIds":["NGS.10","NGS.16"]},{"id":"AM-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief searched the mountains for bezoar goats with long curved horns.","es":"Buscó en las montañas cabras bezoar de cuernos largos y curvos."},"standardIds":["NGS.8"]},{"id":"AM-language-1","skill":"language","difficulty":2,"text":{"en":"The thief practiced a language with its own alphabet, created in the year 405.","es":"Practicó un idioma con su propio alfabeto, creado en el año 405."},"standardIds":["NGS.10"]}]}'::jsonb),
  ('country:AO', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.11,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AO}', '{"iso2":"AO","iso3":"AGO","name":{"en":"Angola","es":"Angola"},"capital":{"name":{"en":"Luanda","es":"Luanda"},"coord":[13.232,-8.836]},"region":"Africa","subregion":"Middle Africa","center":[17.984,-12.183],"flag":{"path":"flags/ao.svg","alt":{"en":"Flag of Angola: red on top and black below, with a yellow half gear wheel, machete and star in the center.","es":"Bandera de Angola: roja arriba y negra abajo, con media rueda dentada, un machete y una estrella amarillos en el centro."}},"languages":[{"en":"Portuguese","es":"Portugués"}],"currency":{"code":"AOA","name":{"en":"Angolan Kwanza","es":"Kuanza angoleño"}},"greeting":{"text":"Olá","ttsLang":"pt-PT","meaning":{"en":"Hello","es":"Hola"}},"facts":[{"en":"Angola is on the Atlantic coast of southern Africa.","es":"Angola está en la costa atlántica del sur de África."},{"en":"The gear on Angola''s flag stands for workers and the machete stands for farmers.","es":"La rueda dentada de la bandera de Angola representa a los trabajadores y el machete, a los campesinos."}],"clues":[{"id":"AO-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: red on top and black below, with a yellow half gear wheel, machete and star in the center.","es":"Dibujó una bandera: roja arriba y negra abajo, con media rueda dentada, un machete y una estrella amarillos en el centro."},"standardIds":["NGS.10","NGS.13"]},{"id":"AO-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief visited Kalandula Falls, one of the biggest waterfalls in Africa.","es":"Visitó las cataratas de Kalandula, unas de las más grandes de África."},"standardIds":["NGS.4","NGS.17"]},{"id":"AO-food-1","skill":"food","difficulty":2,"text":{"en":"The thief tried muamba de galinha, chicken stew cooked with palm oil.","es":"Probó muamba de galinha, un guiso de pollo cocinado con aceite de palma."},"standardIds":["NGS.10","NGS.16"]},{"id":"AO-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief searched for the giant sable antelope, a rare antelope with long curved horns found only here.","es":"Buscó el antílope sable gigante, un antílope raro de cuernos largos y curvos que solo vive aquí."},"standardIds":["NGS.8"]},{"id":"AO-currency-1","skill":"currency","difficulty":3,"text":{"en":"The thief changed money into kwanzas, a currency named after a big river.","es":"Cambió dinero por kwanzas, una moneda que lleva el nombre de un gran río."},"standardIds":["NGS.11"]}]}'::jsonb),
  ('country:AR', 1, 'country', 'published', '{K-2,3-5,6-8}', '{NGS.10,NGS.13,NGS.16,NGS.17,NGS.4,NGS.8}', '{AR}', '{"iso2":"AR","iso3":"ARG","name":{"en":"Argentina","es":"Argentina"},"capital":{"name":{"en":"Buenos Aires","es":"Buenos Aires"},"coord":[-58.399,-34.601]},"region":"Americas","subregion":"South America","center":[-64.173,-33.501],"flag":{"path":"flags/ar.svg","alt":{"en":"Flag of Argentina: light blue, white and light blue stripes, with a golden sun with a face in the middle.","es":"Bandera de Argentina: franjas celeste, blanca y celeste, con un sol dorado con cara en el centro."}},"languages":[{"en":"Spanish","es":"Español"}],"currency":{"code":"ARS","name":{"en":"Argentine Peso","es":"Peso argentino"}},"greeting":{"text":"Hola","ttsLang":"es-AR","meaning":{"en":"Hello","es":"Hola"}},"facts":[{"en":"Aconcagua, in Argentina, is the highest mountain in the Americas.","es":"El Aconcagua, en Argentina, es la montaña más alta de América."},{"en":"Argentina stretches from the tropics almost all the way to Antarctica.","es":"Argentina se extiende desde el trópico casi hasta la Antártida."}],"clues":[{"id":"AR-flag-1","skill":"flag","difficulty":1,"text":{"en":"The thief sketched a flag: light blue, white and light blue stripes, with a golden sun with a face in the middle.","es":"Dibujó una bandera: franjas celeste, blanca y celeste, con un sol dorado con cara en el centro."},"standardIds":["NGS.10","NGS.13"]},{"id":"AR-landmark-1","skill":"landmark","difficulty":2,"text":{"en":"The thief stood in the mist of Iguazú Falls, hundreds of waterfalls on the Iguazú River.","es":"Se mojó con la bruma de las cataratas del Iguazú, cientos de saltos en el río Iguazú."},"standardIds":["NGS.4","NGS.17"]},{"id":"AR-food-1","skill":"food","difficulty":2,"text":{"en":"The thief ate asado, a big beef barbecue, with chimichurri sauce.","es":"Comió asado, una gran parrillada de carne, con salsa chimichurri."},"standardIds":["NGS.10","NGS.16"]},{"id":"AR-animal-1","skill":"animal","difficulty":1,"text":{"en":"The thief watched thousands of Magellanic penguins at Punta Tombo in Patagonia.","es":"Observó miles de pingüinos de Magallanes en Punta Tombo, en la Patagonia."},"standardIds":["NGS.8"]},{"id":"AR-language-1","skill":"language","difficulty":2,"text":{"en":"The thief danced tango and heard a Spanish where ''ll'' sounds like ''sh.''","es":"Bailó tango y escuchó un español donde la ''ll'' suena como ''sh''."},"standardIds":["NGS.10"]}]}'::jsonb),
